const researchResult = $('Extract verified research').first().json;
const analysisResult = $('Run Analyst').first().json;
const writerResult = $input.first().json;
function requireString(result, field, allowEmpty = false) {
  const value = result?.[field];
  if (typeof value !== 'string' || (!allowEmpty && !value.trim())) throw new Error(`Missing or invalid ${field}.`);
  return value;
}
const evidence = requireString(researchResult, 'research_evidence');
const analysis = requireString(analysisResult, 'analysis_result');
const chartFile = requireString(analysisResult, 'chart_url', true);
const html = requireString(writerResult, 'report_html');
const pdfFile = requireString(writerResult, 'pdf_file');

// Only verified research passages may support findings and links in the PDF.
function parsePayload(value, name) {
  try {
    const parsed = JSON.parse(value);
    if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) return parsed;
  } catch {}
  throw new Error(name + ' is not valid JSON.');
}

const researchData = parsePayload(evidence, 'research_evidence');
const analyzedData = parsePayload(analysis, 'analysis_result');
if (researchData.question !== analyzedData.question) {
  throw new Error('The analysis changed the research question.');
}
if (!Array.isArray(researchData.requirements) || !Array.isArray(researchData.accepted_passages) || !Array.isArray(analyzedData.coverage) || !Array.isArray(analyzedData.findings)) {
  throw new Error('Evidence or findings are missing.');
}

const verified = researchData.accepted_passages;
if (!verified.some(passage => passage.relevance === 'direct')) {
  throw new Error('No verified direct evidence; report was not uploaded.');
}
if (analyzedData.findings.length === 0 && !analyzedData.coverage.some(row => row.status === 'supported')) {
  throw new Error('No supported answers; report was not uploaded.');
}
const reqIds = researchData.requirements.map(r => r.id);
if (new Set(reqIds).size !== reqIds.length || analyzedData.coverage.length !== reqIds.length) throw new Error('Required-answer coverage is incomplete or duplicated.');
const missingIds = [];
for (const r of researchData.requirements) {
  const rows = analyzedData.coverage.filter(row => row.id === r.id);
  if (rows.length !== 1) throw new Error(`Coverage missing for ${r.id}.`);
  const row = rows[0];
  if (row.status === 'supported') {
    if (!verified.some(p => p.relevance === 'direct' && p.url === row.source_url && p.quote === row.supporting_quote && p.requirement_ids?.includes(r.id))) throw new Error(`Answer ${r.id} lacks matching verified evidence.`);
  } else if (row.status === 'missing') missingIds.push(r.id);
  else throw new Error(`Invalid coverage status for ${r.id}.`);
}
if (missingIds.length && !/Incomplete research report/i.test(html)) throw new Error('Partial PDF lacks a prominent incomplete label.');
if (!missingIds.length && analyzedData.completeness !== 'complete') throw new Error('Complete answers were not validated.');

const citedUrls = [
  ...html.matchAll(/<a\b[^>]*\bhref\s*=\s*["']([^"']+)["']/gi)
].map(match => match[1].replace(/&amp;/gi, '&'));
const citedSet = new Set(citedUrls);
const verifiedUrls = new Set(verified.map(passage => passage.url));
for (const row of analyzedData.coverage) if (row.status === 'supported' && !citedSet.has(row.source_url)) throw new Error('A required answer is missing its source link in the report.');

for (const finding of analyzedData.findings) {
  if (!verified.some(passage =>
    passage.relevance === 'direct' &&
    passage.url === finding.source_url &&
    passage.quote === finding.supporting_quote
  )) {
    throw new Error('An analysis finding lacks a matching verified source passage.');
  }
  if (!citedSet.has(finding.source_url)) {
    throw new Error('A finding is missing its source link in the report.');
  }
}

for (const url of citedUrls) {
  if (/^https?:\/\//i.test(url) && !verifiedUrls.has(url)) {
    throw new Error('The report cites a URL without verified source evidence.');
  }
}

// Validate local filenames.
if (chartFile !== '' && !/^chart-\d+\.png$/.test(chartFile)) {
  throw new Error('Invalid saved chart filename.');
}

if (!/^report-\d+\.pdf$/.test(pdfFile)) {
  throw new Error('Invalid saved PDF filename.');
}

// Check the chart reference in the report HTML.
const imageSources = [
  ...html.matchAll(
    /<img\b[^>]*\bsrc\s*=\s*["']([^"']+)["'][^>]*>/gi
  )
].map(match => match[1]);

if (chartFile !== '') {
  if (imageSources.filter(src => src === chartFile).length !== 1 || imageSources.some(src => src !== chartFile && !(researchData.image_candidates ?? []).some(c => c.image_url === src))) {
    throw new Error(
      'Report HTML must reference the saved chart filename exactly once.'
    );
  }
} else if (imageSources.some(src => !(researchData.image_candidates ?? []).some(c => c.image_url === src))) {
  throw new Error('Report contains an unverified external image.');
}
const sourceImageSources = imageSources.filter(src => src !== chartFile);
if (sourceImageSources.length > 1) throw new Error('Too many source images.');
for (const src of sourceImageSources) {
  if (!(researchData.image_candidates ?? []).some(c => c.image_url === src && verifiedUrls.has(c.source_url) && citedSet.has(c.source_url))) throw new Error('Source image lacks verified attribution.');
}

// Make a short filename-friendly topic from the report heading.
const heading =
  html.match(/<h1\b[^>]*>([\s\S]*?)<\/h1>/i)?.[1] || 'report';

const topic = heading
  .replace(/<[^>]*>/g, ' ')
  .replace(/&(?:#\d+|#x[\da-f]+|[a-z]+);/gi, ' ')
  .normalize('NFKC')
  .toLowerCase()
  .replace(/[^\p{L}\p{N}]+/gu, '-')
  .slice(0, 70)
  .replace(/^-+|-+$/g, '') || 'report';

return [{
  json: {
    pdf_file: pdfFile,
    report_topic: topic
  }
}];

const research = JSON.parse($('Extract verified research').first().json.research_evidence);
const analysis = JSON.parse($input.first().json.analysis_result);
if (analysis.question !== research.question) throw new Error('Analyst changed the question.');
if (!Array.isArray(analysis.coverage) || !analysis.coverage.some(r => r.status === 'supported')) throw new Error('No supported answer; report writer was skipped to save cost.');
if (!Array.isArray(analysis.findings)) throw new Error('Analyst findings are missing.');
return $input.all();

const question = $('When chat message received').first().json.chatInput;
const raw = $input.first().json.text ?? $input.first().json.output;
if (typeof raw !== 'string') throw new Error('The checklist planner returned no text.');
const value = raw.trim().replace(/^\x60\x60\x60(?:json)?\s*/i, '').replace(/\s*\x60\x60\x60$/, '');
let requirements;
try { requirements = JSON.parse(value); }
catch { throw new Error('Checklist planning failed; research was skipped to save cost.'); }
if (!Array.isArray(requirements) || requirements.length < 1 || requirements.length > 12) throw new Error('Checklist planner returned an invalid number of items.');
const deliveryTask = /\b(?:cit(?:e|es|ed|ing|ation|ations)|references?|source links?|charts?|graphs?|plots?|images?|pdf|reports?|summar(?:y|ies|iz(?:e|es|ing|ation))|format(?:ting)?)\b/i;
requirements = requirements.filter(r => !deliveryTask.test(String(r?.description ?? '')));
if (requirements.length < 1 || requirements.length > 6) throw new Error('Checklist must contain 1-6 factual answers; research was skipped to save cost.');
requirements = requirements.map((r,i) => ({id:'R'+(i+1), description:String(r?.description ?? '').trim()}));
if (requirements.some(r => !r.description || r.description.length > 280)) throw new Error('Checklist contains an invalid fact.');
return [{json:{research_question:question,requirements:JSON.stringify(requirements)}}];

const result = $input.first().json;
const raw = result.research_evidence;
if (typeof raw !== 'string') throw new Error('Research Agent returned no evidence payload.');
const evidence = JSON.parse(raw);
const original = $('When chat message received').first().json.chatInput;
if (evidence.question !== original) throw new Error('Research Agent changed the original question.');
if (!Array.isArray(evidence.requirements) || !Array.isArray(evidence.accepted_passages)) throw new Error('Research checklist or passages missing.');
const nonFact = /^(?:provide|include|cite|list|give)\s+(?:the\s+)?(?:official\s+)?(?:source|sources|citation|citations|references|links)|^(?:official\s+)?(?:source|sources|citation|citations|references|links|chart|comparison)\b/i;
const requirements = evidence.requirements.filter(r => !nonFact.test(String(r.description ?? '').trim()));
if (requirements.length < 1 || requirements.length > 6) throw new Error('No valid factual requirements.');
const ids = new Set(requirements.map(r => r.id));
if (ids.size !== requirements.length) throw new Error('Duplicate requirement IDs.');
evidence.requirements = requirements;
evidence.accepted_passages = evidence.accepted_passages.map(p => ({...p, requirement_ids: (p.requirement_ids ?? []).filter(id => ids.has(id))}));
evidence.uncovered_requirements = (evidence.uncovered_requirements ?? []).filter(r => ids.has(r.id));
if (!evidence.accepted_passages.some(p => p.relevance === 'direct' && p.requirement_ids.length)) throw new Error('No verified direct evidence; no report was created.');
return [{json:{research_evidence:JSON.stringify(evidence)}}];
